// stores/cart.ts: unchanged. `svelte/store` resolves to @pyreon/svelte-compat/store
import { derived, writable } from 'svelte/store'

export const items = writable<string[]>([])
export const count = derived(items, ($items: string[]) => $items.length)

import { computed, signal } from '@pyreon/reactivity'

export function Counter(props: { step: number }) {
  const count = signal(0)
  const doubled = computed(() => count() * 2)
  return (
    <button class="counter" onClick={() => count.update((c) => c + props.step)}>
      {count()} / {doubled()}
    </button>
  )
}
